from pathlib import Path
for base in ['experiments/e1','experiments/e2','experiments/e3']:
 hits=[]
 for p in Path(base).iterdir():
  if p.suffix not in ['.md','.txt']:continue
  text=p.read_text(errors='ignore')
  for line in text.splitlines():
   if any(s in line.lower() for s in ['through degree six','through degree 6','bartholdi','andreadakis proved','a6=','a_6=']):
    hits.append((p.name,line[:600]))
 print(base,hits[:60])

